import{_ as t,o as a,c as s,ai as i}from"./chunks/framework.Df5W0LJX.js";const u=JSON.parse('{"title":"Why CRUD Is the Easy Part of Business Software","description":"Create, read, update, delete is a weekend of work. The business is everything that decides when those four verbs are allowed, and that is where projects actually die.","frontmatter":{"title":"Why CRUD Is the Easy Part of Business Software","description":"Create, read, update, delete is a weekend of work. The business is everything that decides when those four verbs are allowed, and that is where projects actually die.","date":"2026-09-30T00:00:00.000Z","tags":["software","architecture","erp"],"head":[["meta",{"property":"og:title","content":"Why CRUD Is the Easy Part of Business Software"}],["meta",{"property":"og:description","content":"Create, read, update, delete is a weekend of work. The business is everything that decides when those four verbs are allowed, and that is where projects actually die."}],["meta",{"property":"og:url","content":"https://vishnukarthik.me/blog/crud-is-the-easy-part/"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:image","content":"https://vishnukarthik.me/blog/VKP.png"}],["meta",{"name":"twitter:title","content":"Why CRUD Is the Easy Part of Business Software"}],["meta",{"name":"twitter:description","content":"Create, read, update, delete is a weekend of work. The business is everything that decides when those four verbs are allowed, and that is where projects actually die."}],["meta",{"name":"description","content":"Create, read, update, delete is a weekend of work. The business is everything that decides when those four verbs are allowed, and that is where projects actually die."}],["meta",{"property":"article:published_time","content":"2026-09-30T00:00:00.000Z"}]]},"headers":[],"relativePath":"crud-is-the-easy-part.md","filePath":"crud-is-the-easy-part.md"}'),n={name:"crud-is-the-easy-part.md"};function r(o,e,h,d,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="why-crud-is-the-easy-part-of-business-software" tabindex="-1">Why CRUD Is the Easy Part of Business Software <a class="header-anchor" href="#why-crud-is-the-easy-part-of-business-software" aria-label="Permalink to “Why CRUD Is the Easy Part of Business Software”">​</a></h1><p>Every business application starts the same way. A list page, a form, an edit button, a delete button. Four verbs, one table per noun. A competent developer can stand up a working version of it in a weekend, and the demo looks like a finished product.</p><p>It isn&#39;t. It&#39;s the part of the product that was never the problem.</p><p>CRUD answers one question: <em>what is the current state of this record?</em> Business software exists to answer a different one: <em>who is allowed to change this record, from what state, to what state, under which conditions, and what must remain true afterwards?</em></p><p>That second question is where the money, the audits, the lawsuits, and the missed deadlines live.</p><hr><h2 id="what-crud-quietly-assumes" tabindex="-1">What CRUD Quietly Assumes <a class="header-anchor" href="#what-crud-quietly-assumes" aria-label="Permalink to “What CRUD Quietly Assumes”">​</a></h2><p>A CRUD model carries a set of assumptions so basic that nobody writes them down:</p><ol><li><strong>Records are independent.</strong> Editing one row has no consequence for any other.</li><li><strong>Edits are free.</strong> Any field can move to any value at any time.</li><li><strong>Deletes are deletes.</strong> When a row is gone, it was never there.</li><li><strong>There is one actor.</strong> Nobody else is touching this row right now.</li><li><strong>Only the present matters.</strong> The current value is the whole truth.</li></ol><p>Each of those is false the moment real money is involved. Business software is, roughly, the discipline of replacing each one with a rule.</p><table tabindex="0"><thead><tr><th>CRUD assumes</th><th>The business requires</th></tr></thead><tbody><tr><td>Records are independent</td><td>Invariants that span many records</td></tr><tr><td>Any edit is valid</td><td>Legal transitions between defined states</td></tr><tr><td>Delete removes the row</td><td>Reversal, with the original preserved</td></tr><tr><td>One user at a time</td><td>Concurrency control on scarce resources</td></tr><tr><td>Only current state</td><td>History, effective dates, and an audit trail</td></tr></tbody></table><hr><h2 id="_1-a-status-column-is-not-a-state-machine" tabindex="-1">1. A Status Column Is Not a State Machine <a class="header-anchor" href="#_1-a-status-column-is-not-a-state-machine" aria-label="Permalink to “1. A Status Column Is Not a State Machine”">​</a></h2><p>The first place CRUD leaks is the <code>status</code> field. Take an invoice: <code>draft</code>, <code>sent</code>, <code>paid</code>, <code>void</code>.</p><p>In CRUD, that&#39;s a string column. Any user with edit access can set it to any value. Nothing stops <code>paid</code> from being changed back to <code>draft</code>, or a <code>void</code> invoice from being marked <code>sent</code>.</p><p>In the business, the invoice is a small graph with rules on every edge:</p><ul><li><code>draft</code> to <code>sent</code> requires a customer, at least one line item, and a valid tax treatment.</li><li><code>sent</code> to <code>paid</code> requires a matching receipt, and only for the amount actually received.</li><li><code>paid</code> to anything else is not an edit. It&#39;s a credit note, which is a <em>new document</em> that references the old one.</li><li><code>void</code> is terminal.</li></ul><p>The screen for this takes an hour. The transition table, the guards on each edge, the side effects each one triggers, and the tests that prove illegal paths are refused: that&#39;s the actual feature.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// The CRUD version</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">invoice.status </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> req.body.status</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> invoice.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">save</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// The business version</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">invoice.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">transition</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;send&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { actor, at })   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// throws if the edge is illegal</span></span></code></pre></div><p>The difference is not style. In the first version, correctness is the caller&#39;s problem. In the second, it belongs to the model.</p><hr><h2 id="_2-invariants-span-records" tabindex="-1">2. Invariants Span Records <a class="header-anchor" href="#_2-invariants-span-records" aria-label="Permalink to “2. Invariants Span Records”">​</a></h2><p>CRUD validates a row. Businesses have rules that no single row can express:</p><ul><li>Stock on hand can&#39;t go negative.</li><li>Every journal entry must have debits equal to credits.</li><li>The sum of payments against an invoice can&#39;t exceed its total.</li><li>A purchase order can&#39;t be approved by the person who raised it.</li></ul><p>These rules cross tables, and they must hold <em>even when two requests arrive at the same instant</em>. That takes transactions, locks or optimistic versioning, and a decision about where each rule is enforced: in application code, or in the database where nothing can bypass it.</p><p>The failure mode is quiet. Two clerks reserve the last unit of an item a few milliseconds apart. Both saves succeed, because each request validated against a stock count that was true when it started. Nothing crashes. The system is simply wrong, and it stays wrong until someone counts the shelf.</p><hr><h2 id="_3-update-destroys-the-thing-the-business-needs" tabindex="-1">3. Update Destroys the Thing the Business Needs <a class="header-anchor" href="#_3-update-destroys-the-thing-the-business-needs" aria-label="Permalink to “3. Update Destroys the Thing the Business Needs”">​</a></h2><p>An <code>UPDATE</code> statement overwrites. That is precisely what a business can&#39;t afford.</p><p>Consider a price change. If a product&#39;s price is a field on the product and you edit it, every historical sale that referenced that product now appears to have been sold at the new price. The past has been rewritten.</p><p>The business needs to know:</p><ul><li>What was the price <em>at the time of sale</em>?</li><li>Who changed it, and when?</li><li>What was the tax rate on the invoice date, not today?</li><li>What did the report say last quarter, before this correction?</li></ul><p>This is why mature systems copy values onto transactions at the moment they occur, version their reference data with effective dates, and treat financial records as <strong>append-only</strong>. Accounting has never had a delete operation. It has reversing entries: a mistake is corrected by posting the opposite, leaving both visible.</p><p>CRUD&#39;s four verbs have no vocabulary for that. You can bolt on an audit table, but the bolt-on is the real system.</p><hr><h2 id="_4-the-boring-numbers-are-the-dangerous-ones" tabindex="-1">4. The Boring Numbers Are the Dangerous Ones <a class="header-anchor" href="#_4-the-boring-numbers-are-the-dangerous-ones" aria-label="Permalink to “4. The Boring Numbers Are the Dangerous Ones”">​</a></h2><p>Money and tax look trivial until you try to make two reports agree.</p><ul><li>Floating-point currency drifts by fractions that surface as a one-paisa mismatch in a ledger nobody can explain.</li><li>Tax computed per line and tax computed per invoice can differ after rounding, and the correct method is set by regulation, not by preference.</li><li>Multi-currency adds a rate, a date for that rate, and a decision about who bears the difference.</li><li>Discounts, freight, and inclusive versus exclusive pricing each change the order in which arithmetic must be performed.</li></ul><p>None of this appears on a wireframe. All of it appears in a dispute.</p><hr><h2 id="_5-permissions-are-rules-about-state-not-screens" tabindex="-1">5. Permissions Are Rules About State, Not Screens <a class="header-anchor" href="#_5-permissions-are-rules-about-state-not-screens" aria-label="Permalink to “5. Permissions Are Rules About State, Not Screens”">​</a></h2><p>CRUD access control is usually a matrix: role by table, with create, read, update, and delete ticked or not.</p><p>Real authorization depends on the record&#39;s state, its value, and the actor&#39;s relationship to it:</p><ul><li>A manager can approve an expense, but only under a threshold, and never their own.</li><li>A salesperson can edit a quote until it&#39;s sent, then only request a revision.</li><li>Finance can view everything but change nothing after month-end close.</li></ul><p>That&#39;s a policy engine, and it interacts with the state machines above. Every &quot;can edit&quot; is really &quot;can perform <em>this</em> transition, <em>now</em>.&quot;</p><hr><h2 id="_6-where-estimates-go-wrong" tabindex="-1">6. Where Estimates Go Wrong <a class="header-anchor" href="#_6-where-estimates-go-wrong" aria-label="Permalink to “6. Where Estimates Go Wrong”">​</a></h2><p>This is why business software gets mis-scoped so consistently. Requirements are gathered as a list of screens and nouns: customers, products, orders, invoices, payments. Effort is estimated per noun, and per noun it looks small.</p><p>But the cost was never in the nouns. It&#39;s in the <strong>verbs between them and the rules on those verbs</strong>:</p><ul><li>Order confirmation reserves stock, and reservation interacts with warehouse allocation.</li><li>Invoicing posts to the ledger, which interacts with tax, which interacts with period locking.</li><li>Returns reverse all of the above, partially, and in an order that must not break any invariant on the way through.</li></ul><p>A system with ten entities can have a hundred meaningful transitions and several hundred rules across them. Estimating by screen count misses roughly all of that.</p><p>A better unit of estimation is the <strong>transition</strong>: what triggers it, what must be true before, what changes, what must be true after, and what happens if it fails halfway.</p><hr><h2 id="what-follows-from-this" tabindex="-1">What Follows From This <a class="header-anchor" href="#what-follows-from-this" aria-label="Permalink to “What Follows From This”">​</a></h2><p>If CRUD is the easy part, the design priorities invert:</p><ol><li><strong>Model commands, not edits.</strong> <code>approveOrder</code>, <code>postInvoice</code>, <code>reverseReceipt</code>, not <code>PUT /orders/:id</code>.</li><li><strong>Make illegal states unrepresentable, or at least unsaveable.</strong> Push invariants into transactions and database constraints, not just form validation.</li><li><strong>Prefer append-only for anything financial.</strong> Corrections are new records that reference old ones.</li><li><strong>Snapshot at the moment of the event.</strong> Price, tax, rate, and address are copied onto the transaction, not looked up later.</li><li><strong>Test the rules, not the endpoints.</strong> A green CRUD test suite says the framework works. It says nothing about whether the business does.</li><li><strong>Audit by default.</strong> Who, what, when, from which state. Retrofitting this is far harder than building it in.</li></ol><hr><h2 id="the-real-product" tabindex="-1">The Real Product <a class="header-anchor" href="#the-real-product" aria-label="Permalink to “The Real Product”">​</a></h2><p>A CRUD app is a spreadsheet with a login screen. It stores what people typed.</p><p>Business software is a set of <em>enforced agreements</em>: about what a document means, who may move it, what it costs to reverse, and what the books must show afterwards. The forms are the visible five percent. The agreements are the product.</p><p>That&#39;s also why the hard part can&#39;t be templated away. Scaffolding tools will generate every list page and edit form you need in seconds, and they should. But they generate the one layer that was already cheap.</p><p>The work is in the rules, and the rules belong to the business, not the framework.</p><hr><p><em>The screen takes a weekend. The invariants take a year. Price the second one.</em></p>`,64)])])}const m=t(n,[["render",r]]);export{u as __pageData,m as default};
